def solve(inputs: dict) -> float:
    # Linear congruential generator
    # find keys
    start = None
    mult = None
    add = None
    mod = None
    rounds = None
    for k, v in inputs.items():
        kl = k.lower()
        if 'start' in kl or 'begin' in kl or 'initial' in kl or 'seed' in kl:
            start = v
        elif 'mult' in kl or 'mul' in kl:
            mult = v
        elif 'add' in kl or 'incr' in kl or 'plus' in kl:
            add = v
        elif 'mod' in kl:
            mod = v
        elif 'round' in kl or 'iter' in kl or 'step' in kl or 'count' in kl:
            rounds = v
    vals = list(inputs.values())
    if start is None or mult is None or add is None or mod is None or rounds is None:
        # fallback: assume order start, mult, add, mod, rounds
        start, mult, add, mod, rounds = vals[0], vals[1], vals[2], vals[3], vals[4]
    X = int(start)
    for _ in range(int(rounds)):
        X = (int(mult) * X + int(add)) % int(mod)
    return float(X)

