def solve(inputs: dict) -> float:
    # Continued fraction numerator via p_i = a_i*p_{i-1}+p_{i-2}
    terms = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            terms = list(v)
            break
    if terms is None:
        # gather numeric values in order
        terms = [v for v in inputs.values() if isinstance(v, (int, float))]
    p_prev2 = 1  # p_{-1}
    p_prev1 = int(terms[0])  # p_0
    if len(terms) == 1:
        return float(p_prev1)
    for a in terms[1:]:
        p = int(a) * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p
    return float(p_prev1)

